"“村子里还有人在等我。跟紧，左边那条路能上山。”": "「村でみんなが待ってるの。ついてきて、左の道から山に登れるよ」",
"“……耳机先摘一只。你们说，我在听。”": "「……片耳だけ外すね。話して、聞いてるから」",
"千早从小在日本的神社帮忙。祭典散场后，她常留下来收灯笼，也总记得把最靠近台阶的那盏留到最后。到了异世界，她手里的神乐铃能撑起护住同伴的结界，破魔箭能净化不死的怪物。平时她说话轻声细气，可只要还有人没撤到安全的地方，谁也劝不动她先走。一路上，最难开口的反倒是那句“我撑不住了”。她慢慢学着在手开始发抖时，就喊同伴的名字。": "千早は日本の小さな神社で育った巫女。お祭りのあとは残って提灯を片づけ、石段にいちばん近い一つを最後まで灯しておくのが習慣だった。異世界では、神楽鈴で仲間を守る結界を張り、破魔矢で不死の魔物を浄化する。ふだんは小さな声で話すのに、まだ安全な場所まで逃げきれていない人がいるかぎり、誰が言っても先には退かない。この旅でいちばん口にしにくいのは「もう無理」の一言。手が震えはじめたら仲間の名前を呼ぶことを、少しずつ覚えていく。",
"林拓是个爱打游戏的普通初中生。那台旧掌机的电池盖用胶带粘着，他还是天天把它塞进书包。穿越以后，掌机能射出光弹，充一次电就是装填一次弹药。他嘴上喊着“这关我熟”，等光弹打光了，才想起自己根本没问撤退路线。比起打不过的敌人，他更怕有人说“接下来各走各的”。后来有一次，他终于肯蹲在路边给掌机充电，抬头问了一句：“能等我一下吗？”": "林拓はゲーム好きのごく普通の中学生。古い携帯ゲーム機の電池ぶたはテープで留めてあるけれど、毎日カバンに入れて持ち歩いている。異世界ではそのゲーム機が光弾を撃ち、充電はそのまま弾の装填になる。「このステージ知ってる」と言い張っては、弾を撃ちつくしてから逃げ道を聞いていなかったことに気づく。勝てない敵よりも、誰かに「ここからは別々に行こう」と言われるのが怖い。ある日、ようやく道ばたにしゃがんで充電しながら、顔を上げてたずねた。「ちょっと待っててくれる？」",
"莉泽是山脚村庄的小魔女，也是个还没出师的炼金学徒。药水调得不错，毒药调得更好，就是瓶塞上的记号画得太像，有时得迎着光看半天，才敢递给同伴。村民被抓走后，她把能用的瓶瓶罐罐全塞进挎包，独自上山找帮手。她认得山上每一种草，知道哪段坡下过雨就不能走。可一到自己也没去过的岔路口，她还是习惯咬着牙挑一条。直到有一次，她把地图摊在大家中间，承认自己也拿不准。": "リーゼは山のふもとの村に住む小さな魔女で、まだ修行中の錬金術見習い。薬はそこそこ、毒薬はもっと得意だけど、コルクの印が似すぎていて、仲間に渡す前に光にかざしてしばらく確かめることもある。村人がさらわれたあと、使える瓶をありったけカバンに詰めこみ、ひとりで山へ助けを探しに出た。山の草はぜんぶ知っているし、雨のあとに通れなくなる坂もわかる。それでも行ったことのない分かれ道では、歯を食いしばって一本を選んでしまう。ある日、地図をみんなの真ん中に広げて「わたしにもわからない」と打ち明けるまでは。",
"苏音总戴着一副粉色耳机，喜欢把同一段旋律反复听上好几遍。身边太吵的时候，只要把音量调高一点，她就能安静下来。到了异世界，耳机里的音乐能在敌人身上叠起共鸣，等震动积到足够强，她就踩着节拍将它引爆。队伍里数她最安静，可每次开打，大家都会下意识地等她那一拍落下来。有一回，她只顾数拍子，错过了同伴喊她的声音。从那以后，她开始把一边耳罩拨开。": "蘇音はいつもピンクのヘッドホンをつけていて、同じメロディーを何度もくり返し聴くのが好き。まわりがうるさいときは、音量を少し上げれば落ち着ける。異世界では、ヘッドホンの音楽が敵に共鳴を重ね、振動が十分にたまったところで、拍に合わせて爆発させる。パーティでいちばん静かなのに、戦いが始まると、みんな無意識に彼女の一拍を待っている。ある時、拍を数えるのに夢中で、仲間に呼ばれた声を聞きのがした。それからは、片方のイヤーカップを外しておくようになった。",
"天亮了。大家并肩站在晨光里，笑得满脸是灰。": "夜が明けた。みんな朝の光の中に並んで、煤だらけの顔で笑っている。",
"“走吧，往上。”": "「行こう、もっと上へ」",
