"每回合自动叠结界，白拿格挡，稳稳磨死敌人。": "毎ターン結界を重ねてブロックを稼ぎ、じっくり敵を削る。",
"结界爆发流": "結界爆発型",
"先把结界叠高，再一口气换成伤害。": "結界を高く積み上げ、一気にダメージに変える。",
"弹幕流": "弾幕型",
"光弹越多越好，回合结束自动扫射。": "光弾は多いほど強い。ターン終了時に自動で掃射。",
