"不等爆音，直接把共鸣换成伤害。": "爆音を待たず、共鳴をそのままダメージに変える。",
"即将推出": "近日公開",
"元素使 · 艾琳": "エレメンタリスト・エリン",
"法杖 · 元素": "杖・元素",
"剑客 · 顾清寒": "剣客・顧清寒",
"长剑 · 飞剑": "長剣・飛剣",
"霜龙裔 · 希尔薇": "霜竜の末裔・シルヴィ",
"冰枪 · 变身": "氷槍・変身",
"猫耳族 · 米娅": "猫耳族・ミア",
"魔杖 · 云猫": "魔杖・雲猫",
"半吸血鬼 · 绯月": "半吸血鬼・緋月",
"血爪 · 蝙蝠": "血爪・コウモリ",
"麻将社 · 沈雀": "麻雀部・沈雀",
"麻将 · 牌型": "麻雀・役",
"头顶三个元素位，组合火、水、风，「祈唤」出 10 种法术。": "頭上の3つの元素枠で火・水・風を組み合わせ、10種の魔法を「祈喚」する。",
"飞剑加伤害、内力越打越强、剑招连段一口气收招。": "飛剣で威力アップ、内力は戦うほど強まり、剣技の連撃で一気に決める。",
"攒满龙血变身霜龙，三回合内龙息横扫。": "竜血を溜めて霜竜に変身し、3ターン竜の息吹でなぎ払う。",
"云猫团子替你挨打、自己攻击，还会一路长大。": "雲猫のダンゴが攻撃を受け止め、自分で戦い、どんどん成長する。",
"用自己的血换力量，攻击吸血续命，还能放蝙蝠群。": "自らの血を力に変え、攻撃で吸血し、コウモリの群れを放つ。",
"凑对子、刻子、顺子、清一色，胡牌一击定胜负。": "対子・刻子・順子・清一色をそろえ、和了の一撃で決める。",
"“火、水、风……这次搓哪一个呢。”": "「火、水、風……今度はどれを混ぜようかな。」",
"“剑在，人就在。”": "「剣ある限り、私はここにいる。」",
"“……别让我变回那个样子。”": "「……あの姿に戻らせないで。」",
"“团子，拜托你了喵。”": "「団子、お願いにゃ。」",
"“……血的味道，我才不喜欢。”": "「……血の味なんて、好きじゃない。」",
"“这一局，我要胡了。”": "「この局、あがらせてもらう。」",
"艾琳是精灵族的年轻魔法师，天生能同时感受到火、水、风三种元素。族里的长老说她太急躁，总想把三种元素搅在一起用。她偏偏觉得，把元素组合起来才是最有趣的魔法。听说雪山顶上有连通所有世界的门，她想去看看门那边的元素长什么样。": "エリンはエルフ族の若い魔法使いで、火・水・風の三つの元素を同時に感じ取れる。長老たちには「せっかちで、元素をすぐ混ぜたがる」と言われるが、彼女は組み合わせこそ一番面白い魔法だと思っている。雪山の頂にすべての世界をつなぐ門があると聞き、その向こうの元素を見てみたくなった。",
"顾清寒是雪山剑派的弟子。剑派因为「练气」还是「练剑」吵成了两派，她两边都偷偷学了，结果被两边都当成异类。魔王占了山顶后，剑派被赶下了山，她背着剑一个人走下来，想找能一起打回去的人。": "顧清寒は雪山剣派の弟子。剣派は「気を練るか、剣を練るか」で二派に割れ、両方をこっそり学んだ彼女はどちらからも異端扱いされた。魔王が山頂を占拠して剣派が山を追われたあと、彼女はひとり剣を背負って山を下り、共に戦う仲間を探している。",
"希尔薇是远古白龙最后的后裔，住在雪山的冰窟里，外表是冷淡安静的少女。情绪激动时，她会变回霜龙的样子，这让她很害怕自己。山顶的魔王占据了祖先的龙巢，她不得不下山，也不得不学着控制体内的龙血。": "シルヴィは古の白竜の最後の末裔。雪山の氷窟に住み、見た目は冷たく静かな少女だ。感情が高ぶると霜竜の姿に戻ってしまい、それが自分でも怖い。魔王に祖先の竜の巣を奪われ、山を下りて体内の竜血を制御することを学ばなければならない。",
"米娅是人类和猫耳族的混血女孩，两边的族人都不太接纳她，从小只和云猫幼崽团子相依为命。团子的母亲是山里的守护神，被哥布林抓走了。米娅抱着团子上山，嘴上说着「拜托你了喵」，其实最舍不得团子受伤。": "ミアは人間と猫耳族の混血で、どちらの一族にも受け入れられず、雲猫の子ダンゴとだけ寄り添って育った。ダンゴの母は山の守り神で、ゴブリンにさらわれてしまった。ミアはダンゴを抱いて山を登る。「お願いにゃ」と言いながら、本当はダンゴが傷つくのが何より嫌だ。",
"绯月是日本的高中生，被光卷进异世界的人之一。她一直不知道，母亲那边流着吸血鬼的血。古堡的血月唤醒了她的血脉，伯爵认出了她，想把她留下。她拒绝了。她害怕自己越来越不像人类，却又不得不依靠这股力量保护同伴。": "緋月は日本の女子高生で、光に巻き込まれて異世界へ来た一人。母方に吸血鬼の血が流れていることを、彼女は知らなかった。古城の血月がその血を目覚めさせ、伯爵は彼女に気づいて引き留めようとしたが、彼女は拒んだ。人間らしさを失うのが怖いのに、仲間を守るためにはその力に頼るしかない。",
"沈雀是高中麻将社的王牌，平时安安静静，一坐上牌桌就像变了个人。那天她背着装麻将的书包回家，也被那道光卷进了异世界。到了这边，书包里的麻将牌开始发光，凑出牌型就能放出魔法。她的口头禅是：「这一局，我要胡了。」": "沈雀は高校麻雀部のエース。ふだんは物静かなのに、卓につくと別人になる。麻雀牌を入れたカバンを背負って帰る途中、彼女もあの光に巻き込まれた。こちらの世界では牌が光り出し、役をそろえると魔法が放てる。口ぐせは「この局、和了らせてもらうわ」。",
