"「异界来的小老鼠……你们的血，一定很美味。」": "「異界の子ネズミども……お前たちの血は、さぞ美味だろう。」",
"「我只是……替山顶那位看门而已……」": "「私は……山頂のあのお方の門番に過ぎん……」",
"「血月升起吧！」": "「昇れ、血月よ！」",
"（骨头咔嚓咔嚓地重新拼了起来）": "（骨がカタカタと組み直された）",
"复活": "復活",
"血月古堡": "血月の古城",
"哥布林大王倒下了": "ゴブリン大王が倒れた",
"远处山顶的古堡亮起了血红的光。被抓走的村民，就关在那里。": "遠くの山頂の城が血のように赤く光る。さらわれた村人はそこにいる。",
