"{0}化为了灰烬，古堡的血月熄灭了。": "{0}は灰となり、血月は消えた。",
"第二章完 · 感谢游玩！": "第2章クリア・遊んでくれてありがとう！",
"山顶上，还有更深的黑暗在等待……": "山頂では、さらに深い闇が待っている……",
