"守在古堡屋檐上的石头恶魔。石化时几乎打不动，下一回合就会扑下来。": "城の軒にいる石の悪魔。石化中はほぼ無敵、次のターンに襲いかかる。",
"被伯爵诅咒的猎人。血量低于一半就会狂暴。": "伯爵に呪われた狩人。HPが半分を切ると狂暴化する。",
"在墓穴里啃食尸骨的怪物，同伴倒下时会吃掉它们变强。": "墓所で骨をかじる怪物。仲間が倒れると食べて強くなる。",
"亡灵法师用尸块拼出来的巨人。铁钩会把你的牌拽走。": "ネクロマンサーが死体を縫い合わせた巨人。鉄鉤で傷を負わせる。",
"伯爵的新娘。她的吻会吸走你的生命。": "伯爵の花嫁。その口づけは命を吸う。",
"替伯爵唤醒亡者的老巫师。不先打断他，骷髅就杀不完。": "伯爵のために死者を蘇らせる老魔術師。先に倒さないと骸骨が尽きない。",
"伯爵的护卫长，骑着骷髅战马。重甲每回合都在加厚。": "骸骨馬に乗る伯爵の近衛隊長。鎧は毎ターン厚くなる。",
"被伯爵驯服的狼人之王。月圆的回合会全员狂暴。": "伯爵に従う人狼の王。月の下で群れを狂暴化させる。",
"「站住。没有伯爵大人的允许，谁也别想上楼。」": "「止まれ。伯爵様の許しなく、誰も上へは通さん。」",
"「伯爵大人……属下……失职了……」": "「伯爵様……申し訳……ございません……」",
"「嗷呜——今晚的月亮，很适合狩猎。」": "「アオーン——今宵は狩りにいい月だ。」",
"「月亮……沉下去了……」": "「月が……沈んでいく……」",
"（缝合怪炸开了，腐肉溅了一身）": "（縫合巨人が破裂し、腐肉が飛び散った）",
"地牢里的村民": "地下牢の村人",
"铁栅栏后挤着几个面色苍白的村民——正是莉泽村里被抓走的人。": "鉄格子の向こうに青ざめた村人たち——リーゼの村からさらわれた人々だ。",
"撬开牢门：失去 {0} 生命，村民送你一张稀有卡": "扉をこじ開ける：HP{0}を失い、レアカードをもらう",
"村民们哭着向你道谢，塞给你一样东西。": "村人たちは泣いて礼を言い、何かを手渡した。",
"只拿走看守的钥匙串：获得 {0} 金币": "看守の鍵束だけ取る：{0}ゴールドを得る",
"钥匙串上挂着不少值钱的东西。": "鍵束には値打ち物がぶら下がっていた。",
"你答应会回来救他们。": "必ず助けに戻ると約束した。",
"血之泉": "血の泉",
"庭院中央的喷泉涌出血红的泉水，散发着甜腻的气味。": "中庭の噴水から、甘ったるい匂いの真っ赤な水が湧き出ている。",
"喝一口：最大生命 {0}，牌组加入一张「伤口」": "飲む：最大HP{0}、デッキに「傷」を加える",
"力量涌上来，但伤口隐隐作痛。": "力が湧くが、傷がうずく。",
"你捂住鼻子快步走开。": "鼻をつまんで足早に立ち去った。",
"伯爵的书房": "伯爵の書斎",
"书桌上摊着伯爵的日记：“山顶的那位，就快醒了……”": "机には伯爵の日記：「山頂のあのお方が、もうすぐ目覚める……」",
"翻找抽屉：获得一个随机秘宝": "引き出しを探る：ランダムな秘宝を得る",
"你找到了「{0}」。": "「{0}」を見つけた。",
