"无数面镜子里，映出无数个你。": "無数の鏡に、無数の自分が映る。",
"凝视镜子：复制牌组里的一张牌": "鏡を見つめる：デッキのカードを1枚複製",
"镜中的你，把一张牌递了出来。": "鏡の中の自分がカードを差し出した。",
"打碎镜子：删除牌组里的一张牌": "鏡を割る：デッキのカードを1枚削除",
