"墓室中央的黑棺微微打开，缝隙里透出红光。": "墓室の黒い棺が少し開き、赤い光が漏れている。",
"打开：{0}% 拿到秘宝，{1}% 被吸走 {2} 生命": "開ける：{0}%で秘宝、{1}%でHP{2}を吸われる",
"棺材里躺着「{0}」。": "棺の中には「{0}」があった。",
"一只苍白的手伸出来，咬住了你的脖子！": "青白い手が伸び、首筋に噛みつかれた！",
"有些东西，还是别打扰比较好。": "触れない方がいいものもある。",
"亡灵商人": "アンデッド商人",
"兜帽下的绿光眨了眨：“金币？我不要。我要的是……生命。”": "フードの奥で緑の光が瞬く。「金貨？いらん。欲しいのは……命だ。」",
"付 {0} 生命：选一张稀有卡": "HP{0}を払う：レアカードを選ぶ",
"“成交。”商人满意地咯咯笑。": "「取引成立だ。」商人はカラカラと笑った。",
