"喝一口：最大生命 {0}，牌组加入一张「{1}」": "飲む：最大HP{0}、デッキに「{1}」を加える",
"打开：{0} 拿到秘宝，{1} 被吸走 {2} 生命": "開ける：{0}で秘宝、{1}でHP{2}を吸われる",
"哥布林部落的监工，用鞭子驱赶哥布林干活。": "ゴブリン族の監督役。ムチでゴブリンを働かせる。",
