"回合开始获得炼金瓶": "毎ターン錬金瓶",
"抵挡受到的伤害。你的回合开始时清零。": "ダメージを防ぐ。自分のターン開始時に消える。",
"受到的攻击伤害 {0}，每回合减 {1} 层。": "受ける攻撃ダメージ{0}。毎ターン{1}減る。",
"造成的攻击伤害 {0}，每回合减 {1} 层。": "与える攻撃ダメージ{0}。毎ターン{1}減る。",
"每次攻击伤害增加等同于力量的数值。": "攻撃ダメージが筋力ぶん増える。",
"每次获得格挡时额外增加等同于敏捷的数值。": "ブロックを得るたび敏捷ぶん増える。",
"打出后移出本场战斗，不进弃牌堆。": "使うとこの戦闘から除外される。",
"被攻击时，对攻击者造成等同于层数的伤害。": "攻撃されると層数ぶん反撃ダメージ。",
"出牌要花能量，每回合开始恢复为 {0} 点。": "カードにはエナジーが必要。毎ターン{0}に回復。",
"林拓的掌机子弹。回合结束时自动射出，每发对随机敌人造成 {0} 点伤害，然后清零。最多 {1} 发。": "リンのゲーム機の弾。ターン終了時に自動発射、1発{0}ダメージ（ランダムな敵）、その後0に。最大{1}。",
"叠在敌人身上，到 {0} 层自动爆音。": "敵に重なり、{0}で爆音。",
"敌人行动前受到等同层数的伤害（无视格挡），然后减 {0} 层。": "敵は行動前に層数ぶんHPを失い（ブロック無視）、層が{0}減る。",
"魔女的 {0} 费一次性牌，由其他牌生成，用完消耗。": "魔女のコスト{0}の使い切りカード。他のカードで生成。",
"所有角色通用的一次性道具，最多带 {0} 瓶，战斗中点左上角的药水就能用，不花能量。": "全キャラ共通の消耗品。最大{0}本。戦闘中に左上をタップで使用、エナジー不要。",
"叠在自己身上，每回合开始按层数获得格挡，整场战斗保留。": "自分に重なり、毎ターン層数ぶんブロック。戦闘中ずっと残る。",
"共鸣满 {0} 层时，对该敌人造成 {1} 点伤害，之后保留 {2} 层（多出的层数也保留）。": "共鳴が{0}になると{1}ダメージ。その後{2}残る（超過分も残る）。",
"叠在自己身上，每回合开始按层数自动获得格挡，整场战斗不消失。": "自分に重なり、毎ターン層数ぶん自動でブロック。戦闘中は消えない。",
"回合结束时自动射出，每发打随机敌人 {0} 点伤害，然后清零。": "ターン終了時に自動発射、1発{0}ダメージ（ランダムな敵）、その後0に。",
"共鸣满 {0} 层时爆炸，造成 {1} 点伤害，之后保留 {2} 层。": "共鳴{0}で爆発、{1}ダメージ。その後{2}残る。",
"敌人行动前掉等于层数的血（无视格挡），然后层数 {0}。": "敵は行動前に層数ぶんHPを失い（ブロック無視）、その後層が{0}。",
"由其他牌生成的 {0} 费牌，用一次就没了。": "他のカードで生まれるコスト{0}の使い切りカード。",
"打出后整场战斗持续生效。": "戦闘中ずっと有効。",
