"其他敌人各得到共鸣最多的敌人一半的共鸣；只有一个敌人时改为给它 {0} 层共鸣。": "他の敵それぞれに共鳴が最も多い敵の半分の共鳴を付与。敵が1体だけなら、代わりにその敵に共鳴{0}を付与。",
