"对所有敌人造成 {0} + 霜甲层数的伤害。": "敵全体に{0}＋霜甲の数のダメージ。",
"对所有敌人造成 {0} 点伤害，获得 {1} 点格挡；本回合用过火焰瓶时伤害再 {2}。": "敵全体に{0}ダメージ、ブロック{1}を得る。このターン火炎瓶を使っていればダメージ{2}。",
