"把最多 {0} 层霜甲转成等量龙血（不会超过 {1} 点）；霜龙形态下改为保留霜甲、抽 {2} 张牌。消耗。": "霜甲を最大{0}まで同じ量の竜血に変える（竜血は最大{1}まで）。霜竜形態なら霜甲を残したまま、代わりにカードを{2}枚引く。廃棄。",
"把本回合打出的上一张法术再放一张进手牌，算 {0} 次祈唤（本回合没打过法术或祈唤已满 {1} 次时不能打出）。消耗。": "このターン最後に使った術のコピーを手札に加える。祈喚{0}回として数える（このターン術を使っていない、または祈喚が{1}回に達しているときは使えない）。廃棄。",
"抽 {0} 张牌，获得 {1} 点格挡；这是本回合第 {2} 张或之后的技能牌时，结界 {3}。": "カードを{0}枚引き、ブロック{1}を得る。このターン{2}枚目以降のスキルなら、結界{3}。",
"抽 {0} 张牌；团子生命不少于一半时得到 {1} 点能量。": "カードを{0}枚引く。団子のHPが半分以上ならエナジー{1}を得る。",
"抽 {0} 张牌；本回合可以再改一次团子的指令。消耗。": "カードを{0}枚引く。このターンもう一度団子の指示を変えられる。廃棄。",
"抽 {0} 张牌；本回合可以再改一次团子的指令。获得 {1} 点格挡。消耗。": "カードを{0}枚引く。このターンもう一度団子の指示を変えられる。ブロック{1}を得る。廃棄。",
"本回合团子的普通扑击多扑一次（大猫扑杀不会重复）。": "このターン、団子の通常の飛びかかりが1回多くなる（大猫の一撃は重複しない）。",
"本回合团子的普通扑击多扑一次（大猫扑杀不会重复）。抽 {0} 张牌。": "このターン、団子の通常の飛びかかりが1回多くなる（大猫の一撃は重複しない）。カードを{0}枚引く。",
"本回合结束时，前 {0} 发光弹改为打所有敌人。": "このターン終了時、最初の{0}発の光弾が敵全体に当たる。",
"每回合第一次打出和上一张法术配方不同的法术后，对所有敌人造成 {0} 点伤害，抽 {1} 张牌。": "毎ターン最初に、直前の術と違うレシピの術を使った後、敵全体に{0}ダメージを与え、カードを{1}枚引く。",
"每回合结束时，每有 {0} 点内力获得 {1} 点格挡（最多算 {2} 组）。": "毎ターン終了時、内力{0}ごとにブロック{1}を得る（最大{2}回分）。",
"清除自身虚弱和易伤，获得 {0} 点格挡；清除了至少一种时得到 {1} 瓶毒药瓶。消耗。": "自分の弱体と脆弱を消し、ブロック{0}を得る。1つでも消したら毒薬瓶を{1}つ得る。廃棄。",
"生命高于一半时献血 {0}，否则得到 {1} 点鲜血。抽 {2} 张牌。消耗。": "HPが半分より多ければ献血{0}、そうでなければ鮮血を{1}得る。カードを{2}枚引く。廃棄。",
"生命高于一半时献血 {0}，否则得到 {1} 点鲜血。抽 {2} 张牌。获得 {3} 点格挡。消耗。": "HPが半分より多ければ献血{0}、そうでなければ鮮血を{1}得る。カードを{2}枚引く。ブロック{3}を得る。廃棄。",
"结算一个牌型（每回合一次），另获得 {0} 点格挡；结算的是小胡时抽 {1} 张牌。": "役を1つ精算（毎ターン1回）し、ブロック{0}を得る。小和なら、カードを{1}枚引く。",
"给予 {0} 层虚弱（本回合结算过牌型时再 {1}），摸 {2} 张麻将牌。": "弱体{0}を付与（このターン役を精算していれば{1}）。麻雀牌を{2}枚引く。",
"给予目标 {0} 层中毒，其他敌人各得到目标一半的中毒（最多 {1} 层）。": "対象に毒{0}を付与。他の敵それぞれに対象の毒の半分を付与（最大{1}）。",
"给标记目标 {0} 层血痕，获得 {1} 点格挡；有蝙蝠时再 {2}。": "標的に血痕{0}を付与し、ブロック{1}を得る。コウモリがいれば{2}。",
"获得 {0} 点格挡。卸下最多 {1} 发光弹，每发再 {2}。": "ブロック{0}を得る。光弾を最大{1}発外し、1発につき{2}。",
"获得 {0} 点格挡。把最早一格的元素再写入一次（三种元素不变、顺序轮转），然后祈唤。": "ブロック{0}を得る。最も古い枠の元素をもう一度書き込み（元素の構成はそのまま、順番だけ回る）、祈喚する。",
"获得 {0} 点格挡。本回合主动弃过牌则再 {1}，并给 {2} 个随机敌人 {3} 层共鸣。": "ブロック{0}を得る。このターン自分でカードを捨てていれば{1}、ランダムな敵{2}体に共鳴{3}を付与。",
"获得 {0} 点格挡。生命高于一半时献血 {1}；否则鲜血为 {2} 时得到 {3} 点鲜血。消耗。": "ブロック{0}を得る。HPが半分より多ければ献血{1}。そうでなく鮮血が{2}なら、鮮血を{3}得る。廃棄。",
"获得 {0} 点格挡和 {1} 层霜甲；打出前已有至少 {2} 层霜甲时抽 {3} 张牌。": "ブロック{0}と霜甲{1}を得る。使用前に霜甲が{2}以上あれば、カードを{3}枚引く。",
"获得 {0} 点格挡和 {1} 层霜甲；霜龙形态下再抽 {2} 张牌。": "ブロック{0}と霜甲{1}を得る。霜竜形態なら、さらにカードを{2}枚引く。",
"获得 {0} 点格挡；元素位恰好有两种元素时再 {1}。": "ブロック{0}を得る。元素枠の元素がちょうど2種類なら{1}。",
"获得 {0} 点格挡；本回合打出过攻击牌时抽 {1} 张牌。": "ブロック{0}を得る。このターンアタックを使っていれば、カードを{1}枚引く。",
"获得 {0} 点格挡；牌架上有能结算的牌型时再 {1}。": "ブロック{0}を得る。牌架に精算できる役があれば{1}。",
"获得 {0} 点格挡；牌架有至少 {1} 张牌时抽 {2} 张牌，否则摸 {3} 张麻将牌。": "ブロック{0}を得る。牌架に{1}枚以上あればカードを{2}枚引く。そうでなければ麻雀牌を{3}枚引く。",
"获得 {0} 点格挡；鲜血不少于 {1} 时再 {2}；本回合吸过血时抽 {3} 张牌。": "ブロック{0}を得る。鮮血が{1}以上なら{2}。このターン吸血していれば、カードを{3}枚引く。",
