"接下来 {0} 回合团子只能护卫：护卫多挡 {1} 点，团子自己受到的伤害再减半，每次护卫成功米娅获得 {2} 点格挡。合体时打出会先分离。": "次の{0}ターン、団子は護衛のみ：護衛で{1}多く防ぎ、団子の被ダメージをさらに半減。護衛成功ごとにミアがブロック{2}を得る。合体中なら先に分離。",
"团子倒地时：带 {0} 生命回到场上，这回合可以下指令。团子没倒时：团子回复 {1} 生命。消耗。": "団子が倒れている時：HP{0}で復帰し、このターン指示を出せる。倒れていない時：団子がHPを{1}回復。廃棄。",
"每回合第一次射出飞剑时，抽 {0} 张牌并得到 {1} 点能量；飞剑归零时再得到 {2} 把。": "毎ターン最初に飛剣を放った時、カードを{0}枚引きエネルギーを{1}得る。飛剣が0になると{2}本得る。",
"每回合第一次射出飞剑时，抽 {0} 张牌并得到 {1} 点能量；飞剑归零时再得到 {2} 把": "毎ターン最初に飛剣を放った時、カードを{0}枚引きエネルギーを{1}得る。飛剣が0になると{2}本得る",
"养剑流": "養剣型",
"飞剑攒在身上，攻击牌第一击越来越重，回合结束还给格挡。": "飛剣を溜めるほど攻撃カードの初撃が重くなり、ターン終了時にブロックも得る。",
"射剑流": "射剣型",
"养够飞剑后一口气射出去，打出一回合爆发。": "飛剣を十分溜めてから一気に放ち、爆発的なターンを作る。",
"连击流": "連撃型",
"便宜的攻击牌一张接一张，越连越痛。": "安い攻撃カードを次々と繋ぎ、繋ぐほど痛くなる。",
"其他敌人各得到共鸣最多的敌人一半的共鸣（至少 {0} 层）；只有一个敌人时改为给它 {1} 层共鸣。": "他の敵それぞれに共鳴が最も多い敵の半分の共鳴（最低{0}）を付与。敵が1体だけなら、代わりにその敵に共鳴{1}を付与。",
"其他敌人各得到共鸣最多的敌人一半的共鸣（至少 {0} 层），再各 {1}；只有一个敌人时改为给它 {2} 层共鸣。": "他の敵それぞれに共鳴が最も多い敵の半分の共鳴（最低{0}）を付与し、さらに{1}。敵が1体だけなら、代わりにその敵に共鳴{2}を付与。",
"下回合三选一：得到 {0} 点能量 / 攻击伤害 {1} / 受到伤害 {2}。抽 {3} 张牌。": "次のターン、1つ選ぶ：エネルギー{0} / 攻撃ダメージ{1} / 被ダメージ{2}。カードを{3}枚引く。",
"（龙息被打断了！）": "（ブレスが中断された！）",
"小股龙息": "小さなブレス",
"龙蛋": "竜の卵",
"会孵化的龙蛋。头顶的数字归零时，就会孵出一只幼龙。": "孵化しかけの竜の卵。頭上の数字が0になると幼竜が生まれる。",
"孵化中": "孵化中",
"（蛋壳裂开，一只幼龙钻了出来！）": "（殻が割れて、幼竜が這い出してきた！）",
"幼龙": "幼竜",
"刚孵出来的小龙。头顶的数字归零时，会长成满血的成龙。": "生まれたばかりの竜。頭上の数字が0になると、HP満タンの成竜に育つ。",
"啄咬": "かみつき",
"喷火星": "火の粉",
"（幼龙长大了！）": "（幼竜が成長した！）",
"赤焰龙": "紅蓮竜",
"喷火的红龙。蓄力的那个回合打它 {0} 点以上，就能打断龙息。": "火を吐く赤い竜。溜めているターンに{0}以上のダメージを与えるとブレスを中断できる。",
"龙爪": "竜の爪",
"烈焰龙息": "火炎のブレス",
"霜龙": "霜竜",
"冰霜龙。它的龙息会让你冻伤：回合结束时手里剩的牌越多，掉的血越多。": "氷の竜。ブレスで凍傷になる：ターン終了時に手札が多いほどHPを失う。",
"尾扫": "尾払い",
"寒霜龙息": "凍てつくブレス",
"雷龙": "雷竜",
"雷龙。血不多，但龙息伤害最高，还会让你麻痹（下回合少 {0} 点能量）。": "雷の竜。HPは低いがブレスが最強で、麻痺させてくる（次ターンのエネルギー-{0}）。",
"雷爪": "雷爪",
"雷霆龙息": "雷霆のブレス",
"毒沼龙": "毒沼竜",
"毒沼龙。身上全是毒鳞：每次被你攻击，你也中毒 {0} 层。": "毒沼の竜。全身が毒の鱗：攻撃するたびに自分も毒{0}を受ける。",
"毒牙": "毒牙",
"毒雾龙息": "毒霧のブレス",
"双足飞龙": "ワイバーン",
"一直飞在半空。每回合第一次受到的伤害减半。": "常に空を飛んでいる。毎ターン最初に受けるダメージが半減。",
"尾刺": "尾針",
"岩甲龙": "岩甲竜",
"硬化": "硬化",
"龙人战士": "竜人の戦士",
"人形时连砍两刀，化龙后一爪很重、还会长出鳞甲。意图里会提前写「{0}」。": "人の姿では二連斬り、竜化すると重い一撃と鱗甲。意図に事前に「{0}」と表示される。",
"双刃": "双刃",
"化龙": "竜化",
"化人": "人化",
"龙人术士": "竜人の術士",
"人形时给队友加护盾、扔火球；生命低于一半会强制化龙，从此每两回合一口龙息。": "人の姿では味方に盾、火球を投げる。HP半分以下で強制的に竜化し、2ターンごとにブレス。",
"龙鳞护盾": "竜鱗の盾",
"龙息": "竜のブレス",
"双头龙": "双頭竜",
"一火一冰两个头。生命掉到一半时会被砍掉一个头，剩下那个会暴怒（力量 {0}、回 {1} 血）。": "炎と氷の二つの頭。HPが半分になると片方の頭が落ち、残った頭が激怒する（筋力{0}、HP{1}回復）。",
"火息": "火の息",
"冰咬": "氷の噛みつき",
"（冰头被砍下，火头暴怒了！）": "（氷の頭が落ち、炎の頭が激怒した！）",
"（火头被砍下，冰头暴怒了！）": "（炎の頭が落ち、氷の頭が激怒した！）",
"九头蛇": "ヒュドラ",
"每个头咬一口。每掉 {0} 血砍掉一个头，但会长出两个；它身上有灼烧，或者那一下打了 {1} 点以上，就不会再长。": "頭の数だけ噛みつく。HPが{0}減るごとに頭が1つ落ちるが2つ生える。燃焼中か、その一撃が{1}以上なら生えない。",
"群咬": "群れ噛み",
"（断口烧焦了，长不出来！）": "（切り口が焼けて、もう生えない！）",
"（砍掉一个，长出两个！）": "（一つ切ると、二つ生えてきた！）",
"龙人长老": "竜人の長老",
"三种形态轮换：人形召唤龙蛋、半龙形加攻、龙形蓄力龙息。": "三つの姿を巡る：人の姿で卵を召喚、半竜で攻撃強化、竜の姿でブレスを溜める。",
"唤蛋": "卵の召喚",
"半龙化": "半竜化",
"化龙·蓄力": "竜化・溜め",
"古龙之息": "古竜の息",
"紫瞳霜龙": "紫眼の霜竜",
"雪山之巅的远古霜龙，召唤你们来到这个世界的门就在它身后。生命掉到一半会飞上天。": "雪山の頂の古竜。君たちをこの世界に呼んだ門はその背後にある。HPが半分になると空へ舞い上がる。",
"唤雏": "雛呼び",
"冰爪": "氷爪",
"紫霜龙息": "紫霜のブレス",
"寒气": "冷気",
