"极寒吐息": "極寒の吐息",
"开发者": "開発者",
"这个游戏的作者。他能看你的手牌、改你的牌。弱点：一回合打出 {0} 张 {1} 费牌，他就会「{2}」晕一回合。": "このゲームの作者。手札を覗き、カードを書き換える。弱点：1ターンに{1}コストのカードを{0}枚使うと「{2}」で1ターン気絶。",
"看穿": "見抜く",
