"需求变更": "仕様変更",
"灼烧": "火傷",
"回合结束时失去等同层数的生命，然后减 {0} 层": "ターン終了時、層数分のHPを失い、{0}層減る",
"冻伤": "凍傷",
"回合结束时，手里每剩 {0} 张牌失去 {1} 生命（最多按层数算），然后减 {2} 层": "ターン終了時、手札{0}枚ごとにHPを{1}失う（最大で層数分）。その後{2}層減る",
"回合开始时少 {0} 点能量，然后减 {1} 层": "ターン開始時にエネルギー-{0}、その後{1}層減る",
"回合开始时失去等同层数的生命，然后减 {0} 层": "ターン開始時、層数分のHPを失い、{0}層減る",
"鳞甲": "鱗甲",
"孵化": "孵化",
"归零时孵化成幼龙": "0で幼竜が孵る",
"成长": "成長",
"归零时长成满血的成龙": "0でHP満タンの成竜になる",
"头": "頭",
"每个头咬一口": "頭の数だけ噛みつく",
"下回合放出龙息。这回合内受到足够伤害就会被打断": "次ターンにブレス。このターン中に十分なダメージで中断",
"飞翼": "飛翼",
"这回合第一次受到的伤害减半": "このターン最初に受けるダメージが半減",
"屠龙者勋章": "竜殺しの勲章",
"对蓄力中的敌人造成的伤害 {0}。": "溜め中の敵へのダメージ{0}。",
"龙鳞护符": "竜鱗のお守り",
"每场战斗开始时，你获得 {0} 层鳞甲（每次受到的攻击伤害 {1}）。": "戦闘開始時、鱗甲を{0}層得る（受ける攻撃ダメージ{1}）。",
"雪山暖炉": "雪山のストーブ",
"冻伤对你无效。营火休息多回复 {0} 点生命。": "凍傷を無効化。焚き火で休むとHPをさらに{0}回復。",
"龙的宝藏": "竜の財宝",
"山洞深处堆满了金币和宝物，空气里还残留着龙的气息。": "洞窟の奥に金貨と財宝の山。まだ竜の気配が残っている。",
"拿走宝堆：{0} 金币，牌组加入一张「{1}」": "財宝を持ち去る：金貨{0}、デッキに「{1}」を加える",
"金币沉甸甸的，背后却凉飕飕的。": "金貨はずっしり重いが、背筋がぞっとする。",
"只拿一件：随机秘宝，失去 {0} 生命": "一つだけ取る：ランダムな秘宝、HPを{0}失う",
"你没敢多看一眼。": "君は二度見する勇気がなかった。",
"龙蛋巢": "竜の巣",
"岩缝里有一窝还没孵化的龙蛋，摸上去是温热的。": "岩の割れ目に孵化前の竜の卵がある。触ると温かい。",
"打碎蛋：选一张稀有卡": "卵を割る：レアカードを1枚選ぶ",
"蛋壳里流出金色的光。": "殻から金色の光があふれた。",
"带走一颗蛋：最大生命 {0}": "卵を一つ持っていく：最大HP{0}",
"蛋在怀里暖暖的，好像在回应你。": "卵は胸の中で温かく、応えているようだ。",
"你轻手轻脚地走开了。": "君はそっと立ち去った。",
"冰封的冒险者": "氷漬けの冒険者",
"冰墙里冻着一个冒险者，手里还攥着一样东西。": "氷の壁に冒険者が閉じ込められ、何かを握りしめている。",
"凿开冰：失去 {0} 生命，得到随机秘宝": "氷を砕く：HPを{0}失い、ランダムな秘宝を得る",
"翻他的背包：{0} 金币": "荷物を探る：金貨{0}",
"背包里还有一些金币。": "荷物にはまだ金貨が残っていた。",
"你为他默哀了一会儿。": "君は彼のために少し黙祷した。",
"龙人隐者": "竜人の隠者",
"一个白胡子的龙人坐在山洞里，似乎在等你。": "白髭の竜人が洞窟に座り、君を待っていたようだ。",
"拜师：升级 {0} 张牌": "弟子入り：カードを{0}枚強化",
"隐者点了点头。": "隠者はうなずいた。",
"请他看牌：删除 {0} 张牌": "カードを見てもらう：カードを{0}枚削除",
"你向他行了一礼。": "君は彼に一礼した。",
"雪山温泉": "雪山の温泉",
"雪地里冒着热气的温泉，看着就很舒服。": "雪の中で湯気を立てる温泉。見るからに気持ちよさそうだ。",
"泡一泡：回复 {0} 生命": "浸かる：HPを{0}回復",
"浑身都暖起来了。": "体中が温まった。",
"洗去疲惫：最大生命 {0}": "疲れを洗い流す：最大HP{0}",
"身体轻了不少。": "体がずいぶん軽くなった。",
"所有敌人开局带 {0} 点格挡": "すべての敵が開始時にブロック{0}",
"选一张稀有卡": "レアカードを1枚選ぶ",
"精英生命 {0}": "エリートのHP{0}",
"获得一个随机秘宝": "ランダムな秘宝を得る",
"寒潮": "寒波",
"每场战斗开局你带 {0} 层冻伤": "戦闘開始時に凍傷{0}",
"删除 {0} 张牌": "カードを{0}枚削除",
