"最大生命 {0}": "最大HP{0}",
"群龙": "群竜",
"普通战斗多一颗龙蛋": "通常戦闘に竜の卵が1つ増える",
"获得 {0} 瓶药水": "ポーションを{0}本得る",
"强敌": "強敵",
"Boss 攻击 {0}": "ボスの攻撃{0}",
"下一个 Boss 多掉一个秘宝": "次のボスが秘宝を1つ多く落とす",
"永冬之巅": "永冬の頂",
"被删了 {0} 张牌": "カードを{0}枚削除された",
"正负反转！": "正負反転！",
"键盘 · 补丁": "キーボード・パッチ",
"程序报错·无法行动": "エラー発生・行動不能",
"古堡后面的山路，一直通向终年不化的雪峰。": "古城の裏の山道は、万年雪の峰へと続いていた。",
"风里传来龙的长啸，一声接着一声。": "風に乗って、竜の咆哮が次々と響いてくる。",
"“那双紫色的眼睛……就在山顶。”": "「あの紫の眼は……山頂にいる。」",
"存档……保存好了。下次再来，我还带掌机。": "セーブ……完了。次来るときも携帯ゲーム機を持ってくるよ。",
"回去以后，我想把这一路的声音写成歌。": "帰ったら、この旅の音を歌にしたい。",
"神社的铃铛响了……我到家了。": "神社の鈴が鳴った……ただいま。",
"你们走吧。村子……我会替你们守着的。": "行って。村は……私があなたたちの代わりに守るから。",
"火、水、风……都归于平静了。": "火も、水も、風も……すべて静まった。",
"剑收入鞘。这一程，走完了。": "剣を鞘に。この旅は、終わった。",
"我不是龙，也不只是人。我是你们的同伴。": "私は竜じゃない、ただの人間でもない。あなたたちの仲間だ。",
"团子，我们也回家吧喵。": "団子、私たちも帰ろうにゃ。",
"天亮了。……原来我也能站在太阳底下。": "夜が明けた。……私も、陽の下に立てるんだ。",
"这一关，总算是通了。下个版本见。": "やっとクリアできた。次のバージョンで会おう。",
"门对面，是放学路上的那条街。": "門の向こうは、下校途中のあの通りだった。",
"大家互相看了一眼，谁也没先迈步。": "みんな顔を見合わせ、誰も先に踏み出さなかった。",
"“……走吧，回家。”": "「……行こう、帰ろう。」",
