"「异界的孩子们……把你们叫来的门，就在我身后。」": "「異界の子らよ……お前たちを呼んだ門は、我の背後にある。」",
"「留下来吧，幼崽。这座山本该是你的。」": "「残るがいい、幼子よ。この山はお前のものであるべきだ。」",
"「那就让我看看——你们能爬多高。」": "「では見せてみよ——どこまで登れるか。」",
"「门……开了。去吧，去你们想去的地方。」": "「門は……開いた。行け、行きたい場所へ。」",
"「这一关……其实我自己都没打过。」": "「このステージ……実は自分でもクリアしたことないんだ。」",
"「嗯……没什么好削的。」": "「うーん……ナーフするものがないな。」",
"「调试一下……」": "「ちょっとデバッグ……」",
"「你手里的牌，我都看到了。」": "「君の手札、全部見えてるよ。」",
"「这两张，删了。」": "「この2枚、削除。」",
"「这张……正负反过来试试。」": "「これ……正負を逆にしてみよう。」",
"「程序报错了？！」": "「エラーが出た！？」",
"「这个数值不对……Ctrl+Z。」": "「この数値はおかしい……Ctrl+Z。」",
"「行，你们比我会玩。门在上面，替我向那条龙问好。」": "「わかった、君たちの方が上手い。門は上だ。あの竜によろしく。」",
"「这张，用不上了。」": "「これは、もう要らない。」",
"「{0}」太强了，削。」": "「「{0}」は強すぎる、ナーフ。」",
"「{0}」借我用用。」": "「「{0}」、ちょっと借りるね。」",
"反转": "反転",
"给手牌打「{0}」让它越打越强；或者堆 {1} 费脚本，一回合打出第 {2} 张 {3} 费牌时触发「{4}」。": "手札に「{0}」を当ててどんどん強くする。または{1}コストのスクリプトを重ね、1ターンに{3}コストのカードを{2}枚使うと「{4}」が発動。",
"“这张牌……我可以改。”": "「このカード……書き換えられるよ。」",
"这个游戏的作者。在山顶的门前守了很久，最后决定自己也下场玩一把。": "このゲームの作者。山頂の門を長く守ってきたが、ついに自分でもプレイすることにした。",
"古堡的血月熄灭了，被关押的村民们重获自由。": "古城の血の月が消え、囚われていた村人たちは自由になった。",
