"开发者让开了路，嘴里还在嘀咕着数值。": "開発者は道を空けたが、まだ数値のことをぶつぶつ言っている。",
"风雪的尽头，一条银白的巨龙伏在发光的门前。": "吹雪の果て、輝く門の前に銀白の巨竜が伏せていた。",
