"紫瞳霜龙倒下了。门的对面，是放学路上的那条街。": "紫眼の霜竜は倒れた。門の向こうは、下校途中のあの通りだ。",
"门的上方，还有一节台阶。": "門の上に、まだ一段の階段がある。",
