"感谢游玩！": "プレイしてくれてありがとう！",
"紫瞳霜龙倒下了，回家的门打开了。": "紫眼の霜竜は倒れ、帰り道の門が開いた。",
"全部通关 · 感谢游玩！": "全章クリア・プレイしてくれてありがとう！",
