"敌人受到的每次攻击伤害减少等同层数（最多减一半）；一次受到 {0} 点以上的攻击会打碎 {1} 层。": "敵が受ける攻撃ダメージが層数分減る（最大で半分まで）。{0}以上の一撃で{1}層砕ける。",
"回合结束时，手里每剩 {0} 张牌失去 {1} 生命（最多按层数算），然后减 {2} 层。": "ターン終了時、手札{0}枚ごとにHPを{1}失う（最大で層数分）。その後{2}層減る。",
"回合结束时失去等同层数的生命，然后减 {0} 层。": "ターン終了時、層数分のHPを失い、{0}層減る。",
"回合开始时少 {0} 点能量，然后减 {1} 层。": "ターン開始時にエネルギー-{0}、その後{1}層減る。",
"龙下回合要放龙息。蓄力的那个回合里打它足够多的伤害，就能打断。": "竜が次のターンにブレスを吐く。溜めのターン中に十分なダメージを与えれば中断できる。",
"补丁": "パッチ",
"这张牌本场伤害或格挡增加，牌面显示版本号。": "この戦闘中、このカードのダメージかブロックが増える。カードにバージョン番号が表示される。",
"合体时攻击加成变成团子攻击力的三分之二": "合体中、攻撃ボーナスが団子の攻撃力の3分の2になる",
"合体时，攻击的加成从团子攻击力的三分之一变成三分之二。": "合体中、攻撃ボーナスが団子の攻撃力の3分の1から3分の2になる。",
"合体时，攻击的加成从团子攻击力的三分之一变成三分之二；合体时每回合多 {0} 点格挡。": "合体中、攻撃ボーナスが団子の攻撃力の3分の1から3分の2になる。合体中は毎ターンのブロック+{0}。",
"每把让攻击牌的第一击 {0} 伤害，每 {1} 把再额外 {2}；回合结束每 {3} 把给 {4} 点格挡；可以射出（最多 {5} 把）": "1本ごとにアタックの初撃{0}ダメージ、{1}本ごとにさらに{2}。ターン終了時{3}本ごとにブロック{4}。発射できる（最大{5}本）",
"每把飞剑给攻击牌第一击的加成从 {0} 变成 {1}（每 {2} 把仍再额外 {3}）。": "飛剣1本ごとの初撃ボーナスが{0}から{1}になる（{2}本ごとの追加{3}はそのまま）。",
