"门后的裂隙": "門の向こうの裂け目",
"开发者让开了路。山顶的门半开着，门缝里涌出紫红色的光和硫磺味。": "開発者が道を譲った。山頂の門は半開きで、隙間から紫紅の光と硫黄の匂いが溢れ出している。",
"紫瞳霜龙就守在门的另一头——可门和它之间，空间已经裂开了。": "紫眼の霜竜は門の向こうで待っている——だがその間で、空間そのものが裂けていた。",
"踏进裂隙": "裂け目に踏み込む",
"裂隙里没有风雪，只有烧焦的岩石和低语声。": "裂け目に雪はなく、焦げた岩とささやき声だけがあった。",
"小小的、抱着锁链的影子，在岩缝里咯咯地笑。": "鎖を抱えた小さな影が、岩の隙間でけらけらと笑っている。",
"“门那边漏出来的东西……原来是这些。”": "「門の向こうから漏れてたのは……これだったのか。」",
"门开了": "門が開いた",
"霜龙倒在门前，门的那一边，黑色的铠甲缓缓走了出来。": "霜竜が門の前に倒れた。門の向こうから、黒い鎧がゆっくりと歩み出てくる。",
"「龙守着门，就是为了关住我。」": "「竜が門を守っていたのは、我を閉じ込めるためだ。」",
"迎战魔王": "魔王に挑む",
"深渊之主化成了黑烟。门的对面，是放学路上的那条街。": "深淵の主は黒い煙となって消えた。門の向こうは、学校帰りのあの道だった。",
"深渊之主倒下了，回家的门打开了。": "深淵の主が倒れ、帰りの門が開いた。",
"进入第三章·下半：魔界裂隙（回复 30% 生命）": "第三章・後半：魔界の裂け目へ（HPを30%回復）",
